package com.hbm.missile.launchpad.standard;
import api.hbm.item.IDesignatorItem;import com.hbm.api.computer.*;import com.hbm.api.machine.IFluidCopiable;import com.hbm.energy.*;import com.hbm.entity.missile.*;import com.hbm.fluid.*;import com.hbm.fluid.network.*;import com.hbm.interfaces.IBomb.BombReturnCode;import com.hbm.item.battery.*;import com.hbm.item.missile.MissileItem;import com.hbm.machine.foundry.crucible.ThermalMachine;import com.hbm.missile.completion.MissileContent;import com.hbm.multiblock.DummyableBlock;import com.hbm.radar.IRadarCommandReceiver;import com.hbm.registry.HbmSounds;import java.util.*;import java.util.function.Consumer;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.SoundSource;import net.minecraft.util.Mth;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.*;
/** Complete source normal pad: reload delay, native four-corner ports, two fuels and seven OC callbacks moved to CC. */
public class StandardLaunchPadBlockEntity extends ThermalMachine implements EnergyReceiver,SidedEnergyConnector,StandardFluidReceiver,IFluidCopiable,ComputerControl,IRadarCommandReceiver {
 public static final long MAX_POWER=100000;public static final int MISSING=0,LOADING=1,READY=2;public long power;public int delay,state,prevRedstonePower,redstonePower;public boolean muffled,tilted;public ItemStack toRender=ItemStack.EMPTY;public final FluidTank[] tanks={new FluidTank(HbmFluids.NONE,24000),new FluidTank(HbmFluids.NONE,24000)};public final Set<BlockPos> activatedBlocks=new HashSet<>(4);private final Map<BlockPos,PowerNode> nodes=new LinkedHashMap<>();private final Map<BlockPos,FluidPorts> fluidPorts=new LinkedHashMap<>();
 public static Consumer<Smoke> smoke=s->{};public record Smoke(Level level,double x,double y,double z,double mx,double my,double mz){}
 public StandardLaunchPadBlockEntity(BlockPos pos,BlockState state){this(StandardLaunchPadContent.ENTITY.get(),pos,state);}
 protected StandardLaunchPadBlockEntity(net.minecraft.world.level.block.entity.BlockEntityType<?> type,BlockPos pos,BlockState state){super(type,pos,state,7);}@Override protected String title(){return "container.launchPad";}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new StandardLaunchPadMenu(id,inventory,this,worldPosition);}
 public static List<BlockPos> portPositions(BlockPos core){return List.of(core.offset(-1,0,-1),core.offset(1,0,-1),core.offset(1,0,1),core.offset(-1,0,1));}public static Direction[] portSides(BlockPos core,BlockPos port){return new Direction[]{port.getX()<core.getX()?Direction.WEST:Direction.EAST,port.getZ()<core.getZ()?Direction.NORTH:Direction.SOUTH};}
 protected void updatePorts(ServerLevel server){var positions=actualPortPositions().stream().filter(p->server.hasChunkAt(p)&&server.getBlockState(p).is(getBlockState().getBlock())&&DummyableBlock.isPort(server.getBlockState(p))).toList();if(!nodes.keySet().equals(new LinkedHashSet<>(positions))||nodes.values().stream().anyMatch(PowerNode::isExpired)){disconnect();for(var p:positions){var connections=Arrays.stream(actualPortSides(p)).map(side->new NodeConnection(p.relative(side),side)).toArray(NodeConnection[]::new);var node=new PowerNode(p).setConnections(connections);HbmEnergy.nodespace(server).createNode(node);nodes.put(p,node);fluidPorts.put(p,new FluidPorts(new BlockPos[]{p},connections));}}for(var node:nodes.values())if(node.hasValidNet())node.addReceiver(this);for(var port:fluidPorts.values())port.update(server,this);}
 private void disconnect(){if(level instanceof ServerLevel server){for(var node:nodes.values())if(!node.isExpired())HbmEnergy.nodespace(server).destroyNode(node);for(var port:fluidPorts.values())port.remove(server);}nodes.clear();fluidPorts.clear();}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
 public static void tick(Level level,BlockPos pos,BlockState state,StandardLaunchPadBlockEntity pad){if(level instanceof ServerLevel server){if(pad.delay>0)pad.delay--;if(!pad.isMissileValid()||!pad.hasFuel())pad.delay=100;pad.state=!pad.hasFuel()||!pad.isMissileValid()?MISSING:pad.delay>0?LOADING:READY;pad.serverBaseTick(server);}else if(!level.getEntitiesOfClass(EntityMissileBaseNT.class,new AABB(pos.getX()-.5,pos.getY(),pos.getZ()-.5,pos.getX()+1.5,pos.getY()+10,pos.getZ()+1.5)).isEmpty())for(int i=0;i<15;i++){var dir=DummyableBlock.facing(state);if(level.random.nextBoolean())dir=dir.getOpposite();if(level.random.nextBoolean())dir=dir.getCounterClockWise();float mx=(float)(level.random.nextGaussian()*.15F+.75)*dir.getStepX(),mz=(float)(level.random.nextGaussian()*.15F+.75)*dir.getStepZ();smoke.accept(new Smoke(level,pos.getX()+.5,pos.getY()+.25,pos.getZ()+.5,mx,0,mz));}}
 protected void serverBaseTick(ServerLevel server){this.updatePorts(server);if(this.redstonePower>0&&this.prevRedstonePower<=0)this.launchFromDesignator();this.prevRedstonePower=this.redstonePower;this.chargeBattery();var inventory=this.slots.toArray(ItemStack[]::new);this.tanks[0].loadTank(3,4,inventory);this.tanks[1].loadTank(5,6,inventory);for(int i=3;i<7;i++)this.slots.set(i,inventory[i]);if(this.isMissileValid())this.setFuel((MissileItem)this.slots.get(0).getItem());this.toRender=this.slots.get(0).copyWithCount(1);this.sync(250);}
 protected List<BlockPos> actualPortPositions(){return portPositions(worldPosition);}protected Direction[] actualPortSides(BlockPos port){return portSides(worldPosition,port);}
 protected void chargeBattery(){if(power<0){power=0;return;}if(power>MAX_POWER){power=MAX_POWER;return;}var stack=slots.get(2);if(stack.getItem() instanceof CreativeBatteryItem){power=MAX_POWER;return;}if(stack.getItem() instanceof HbmBattery battery){long amount=Math.min(Math.min(MAX_POWER-power,battery.getDischargeRate(stack)),battery.getCharge(stack));battery.dischargeBattery(stack,amount);power+=amount;}}
 public void setFuel(MissileItem missile){switch(missile.fuel){case ETHANOL_PEROXIDE->{tanks[0].setTankType(HbmFluids.ETHANOL);tanks[1].setTankType(HbmFluids.PEROXIDE);}case KEROSENE_PEROXIDE->{tanks[0].setTankType(HbmFluids.KEROSENE);tanks[1].setTankType(HbmFluids.PEROXIDE);}case KEROSENE_LOXY->{tanks[0].setTankType(HbmFluids.KEROSENE);tanks[1].setTankType(HbmFluids.OXYGEN);}case JETFUEL_LOXY->{tanks[0].setTankType(HbmFluids.KEROSENE_REFORM);tanks[1].setTankType(HbmFluids.OXYGEN);}default->{}}}
 public boolean isMissileValid(){return isMissileValid(slots.get(0));}public boolean isMissileValid(ItemStack stack){return !stack.isEmpty()&&stack.getItem() instanceof MissileItem missile&&missile.launchable;}public boolean hasFuel(){return power>=75000&&slots.get(0).getItem() instanceof MissileItem missile&&tanks[0].getFill()>=missile.fuelCap&&tanks[1].getFill()>=missile.fuelCap;}public boolean canLaunch(){return isMissileValid()&&hasFuel()&&isReadyForLaunch();}public int getGaugeState(int tank){return slots.get(0).getItem() instanceof MissileItem missile&&missile.fuel!=MissileItem.MissileFuel.SOLID?(tanks[tank].getFill()>=missile.fuelCap?1:-1):0;}
 public Entity instantiateMissile(int targetX,int targetZ){var kind=MissileContent.kind(slots.get(0));if(kind==null)return null;var entity=kind.launch.create(level,worldPosition.getX()+.5F,worldPosition.getY()+(float)getLaunchOffset(),worldPosition.getZ()+.5F,targetX,targetZ);if(entity instanceof EntityMissileBaseNT missile){com.hbm.logging.SourceActionLog.info("[MISSILE] Tried to launch missile at {} / {} / {} to {} / {}!",worldPosition.getX(),worldPosition.getY(),worldPosition.getZ(),worldPosition.getX(),worldPosition.getZ());missile.setRotation((byte)DummyableBlock.facing(getBlockState()).get3DDataValue());}return entity;}
 protected void finalizeLaunch(Entity entity){if(entity instanceof EntityMissileBaseNT missile)missile.trackingRange=500;if(entity instanceof EntityMissileAntiBallistic missile)missile.trackingRange=500;level.addFreshEntity(entity);level.playSound(null,worldPosition.getX()+.5,worldPosition.getY(),worldPosition.getZ()+.5,HbmSounds.get("weapon.missileTakeOff"),SoundSource.BLOCKS,2F,1F);power-=75000;if(slots.get(0).getItem() instanceof MissileItem item){tanks[0].setFill(tanks[0].getFill()-item.fuelCap);tanks[1].setFill(tanks[1].getFill()-item.fuelCap);}removeItem(0,1);onLaunch();setChanged();}
 protected boolean isReadyForLaunch(){return delay<=0;}protected double getLaunchOffset(){return 1;}protected void onLaunch(){delay=100;}
 public BombReturnCode launchFromDesignator(){if(!canLaunch())return BombReturnCode.ERROR_MISSING_COMPONENT;boolean needs=MissileContent.kind(slots.get(0))!=MissileContent.Kind.ANTI_BALLISTIC;int tx=worldPosition.getX(),tz=worldPosition.getZ();if(slots.get(1).getItem() instanceof IDesignatorItem designator){if(needs){if(!designator.isReady(level,slots.get(1),tx,worldPosition.getY(),tz))return BombReturnCode.ERROR_MISSING_COMPONENT;var target=designator.getCoords(level,slots.get(1),tx,worldPosition.getY(),tz);tx=Mth.floor(target.x);tz=Mth.floor(target.z);}}else if(needs)return BombReturnCode.ERROR_MISSING_COMPONENT;return launchToCoordinate(tx,tz);}
 public BombReturnCode launchToCoordinate(int x,int z){if(!canLaunch())return BombReturnCode.ERROR_MISSING_COMPONENT;var entity=instantiateMissile(x,z);if(entity==null)return BombReturnCode.ERROR_MISSING_COMPONENT;finalizeLaunch(entity);return BombReturnCode.LAUNCHED;}public BombReturnCode launchToEntity(Entity target){if(!canLaunch())return BombReturnCode.ERROR_MISSING_COMPONENT;var entity=instantiateMissile(Mth.floor(target.getX()),Mth.floor(target.getZ()));if(entity==null)return BombReturnCode.ERROR_MISSING_COMPONENT;if(entity instanceof EntityMissileAntiBallistic abm)abm.tracking=target;finalizeLaunch(entity);return BombReturnCode.LAUNCHED;}
 @Override public boolean sendCommandPosition(int x,int y,int z){return launchToCoordinate(x,z)==BombReturnCode.LAUNCHED;}@Override public boolean sendCommandEntity(Entity target){return launchToEntity(target)==BombReturnCode.LAUNCHED;}public void updateRedstonePower(BlockPos part){boolean powered=level.hasNeighborSignal(part),contained=activatedBlocks.contains(part);if(!contained&&powered){activatedBlocks.add(part.immutable());if(redstonePower==-1)redstonePower=0;redstonePower++;}else if(contained&&!powered){activatedBlocks.remove(part);redstonePower--;if(redstonePower==0)redstonePower=-1;}setChanged();}
 @Override public long getPower(){return power;}@Override public long getMaxPower(){return MAX_POWER;}@Override public void setPower(long value){power=value;setChanged();}@Override public boolean isLoaded(){return !isRemoved()&&level!=null;}@Override public boolean canConnect(Direction side){return side!=Direction.UP&&side!=Direction.DOWN;}@Override public boolean canConnect(HbmFluidType type,Direction side){return canConnect(side);}@Override public FluidTank[] getAllTanks(){return tanks;}@Override public FluidTank[] getReceivingTanks(){return tanks;}@Override public FluidTank getTankToPaste(){return null;}
 @Override public long energyStored(){return power;}@Override public long energyCapacity(){return MAX_POWER;}@Override public List<TankView> tanks(){return Arrays.stream(tanks).map(t->new TankView(t.getTankType(),t.getFill(),t.getMaxFill())).toList();}@Override public List<ProgressView> progressBars(){return List.of();}@Override public boolean stillValid(Player p){return level!=null&&level.getBlockEntity(worldPosition)==this&&p.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=144;}@Override public int[] getSlotsForFace(Direction side){return new int[]{0};}@Override public boolean canPlaceItem(int slot,ItemStack stack){return slot==0&&isMissileValid(stack);}
 @Override protected void saveMachine(CompoundTag tag){tag.putLong("power",power);tag.putInt("delay",delay);tag.putInt("state",state);tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);tanks[0].writeToNBT(tag,"t0");tanks[1].writeToNBT(tag,"t1");tag.putInt("redstonePower",redstonePower);tag.putInt("prevRedstonePower",prevRedstonePower);var active=new CompoundTag();int i=0;for(var p:activatedBlocks){active.putInt("x"+i,p.getX());active.putInt("y"+i,p.getY());active.putInt("z"+i,p.getZ());i++;}tag.put("activatedBlocks",active);if(!toRender.isEmpty())tag.put("display",toRender.save(level.registryAccess()));}
 @Override protected void loadMachine(CompoundTag tag){power=tag.getLong("power");delay=tag.getInt("delay");state=tag.getInt("state");muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");tanks[0].readFromNBT(tag,"t0");tanks[1].readFromNBT(tag,"t1");redstonePower=tag.getInt("redstonePower");prevRedstonePower=tag.getInt("prevRedstonePower");activatedBlocks.clear();var active=tag.getCompound("activatedBlocks");for(int i=0;i<active.getAllKeys().size()/3;i++)activatedBlocks.add(new BlockPos(active.getInt("x"+i),active.getInt("y"+i),active.getInt("z"+i)));toRender=tag.contains("display")&&level!=null?ItemStack.parseOptional(level.registryAccess(),tag.getCompound("display")):ItemStack.EMPTY;}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;}
 @Override public String computerType(){return "ntm_launch_pad";}@Override public String[] computerMethods(){return new String[]{"getEnergyInfo","getFluid","canLaunch","getTier","launch","launchEntity","getPos"};}@Override public Object[] callComputer(String method,ComputerArguments args){return switch(method){case "getEnergyInfo"->new Object[]{power,MAX_POWER};case "getFluid"->new Object[]{tanks[0].getFill(),tanks[0].getMaxFill(),tanks[0].getTankType().getUnlocalizedName(),tanks[1].getFill(),tanks[1].getMaxFill(),tanks[1].getTankType().getUnlocalizedName()};case "canLaunch"->new Object[]{canLaunch()};case "getTier"->isMissileValid()?new Object[]{((MissileItem)slots.get(0).getItem()).tier.ordinal()}:new Object[]{};case "launch"->new Object[]{canLaunch()&&sendCommandPosition(args.checkInteger(0),-1,args.checkInteger(1))};case "launchEntity"->{var target=level.getEntity(args.checkInteger(0));yield new Object[]{canLaunch()&&target!=null&&target.isAlive()&&sendCommandEntity(target)};}case "getPos"->new Object[]{worldPosition.getX(),worldPosition.getY(),worldPosition.getZ()};default->throw new ComputerException("No such method");};}
}
